  /// Why, recorded with the change.
  final String reason;
  final Ext? ext;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'badgeId': badgeId,
        if (requestable != null) 'requestable': requestable!,
        if (shareableOutside != null) 'shareableOutside': shareableOutside!,
        if (holdersVisibleTo != null)
          'holdersVisibleTo': holdersVisibleTo!.value,
        if (owners != null) 'owners': owners!,
        'reason': reason,
        if (ext != null) 'ext': ext!,
      };
}

