le":{"type":"boolean","description":"Whether one member may hold the badge more than once, each giving an award of its own (VTI-BDG-022). Always true for a kudos badge."},"requestable":{"type":"boolean","description":"Community badges only. Whether a member may ask for it: a request to join its badge group, decided by its owners (VTI-BDG-014). Absent reads as false."},"listed":{"type":"boolean","description":"Whether members who do not hold the badge see it in the community\'s badge list. An unlisted badge is seen by its holders, its owners and administrators."},"shareableOutside":{"type":"boolean","description":"Community badges only. Whether its holders may show it outside the community, which decides the credential\'s regime: short-lived and renewed with no status when false, long-lived with a status in the community\'s own status set when true (VTI-BDG-061, VTI-BDG-062). Absent reads as false."},"groupId":{"\$ref":"#/\$defs/GroupId","description":"The badge group that backs a community badge: its managers are the badge\'s owners, its members the holders, its DID the credential\'s issuer."},"state":{"\$ref":"#/\$defs/BadgeState"},"holderCount":{"type":"integer","minimum":0,"description":"Holders who show the badge. Only to callers who may see the holders."},"createdAt":{"type":"string","format":"date-time"},"createdBy":{"\$ref":"#/\$defs/EntryId"},"updatedAt":{"type":"string","format":"date-time"},"retiredAt":{"type":"string","format":"date-time"},"ext":{"\$ref":"#/\$defs/Ext","description":"Ecosystem-defined extension members per SPEC.md §4.5.1. An extension member MUST NOT carry authority."}}},"BadgeState":{"title":"BadgeState","description":"`active`: may be given and shown. `retired`: kept for its holders\' own history, never given, never shown to members who do not hold it (VTI-BDG-005).","type":"string","enum":["active","retired"]},"BadgeCriteria":{"title":"BadgeCriteria","type":"string","minLength":1,"maxLength":1000,"description":"How the badge is earned,