a type of the stored bytes."},"size":{"type":"integer","minimum":1,"maximum":262144,"description":"Size in bytes of the stored bytes."},"url":{"type":"string","format":"uri","maxLength":2048,"description":"Projection only: a URL the viewer can fetch the image from until `urlExpiresAt`."},"urlExpiresAt":{"type":"string","format":"date-time","description":"Projection only: when `url` stops working."}}}}}';

