$ref":"#/\$defs/BadgeId"},"kind":{"\$ref":"#/\$defs/BadgeKind"},"name":{"\$ref":"#/\$defs/BadgeName"},"description":{"\$ref":"#/\$defs/BadgeDescription"},"criteria":{"\$ref":"#/\$defs/BadgeCriteria"},"image":{"\$ref":"#/\$defs/CardBlobRef","description":"The badge\'s picture, re-encoded and stored by the community (vtc/badges/images/upload), read with vtc/badges/images/get. `url` and `urlExpiresAt` MAY appear in a projection as for a card picture; for a badge whose holders may show it outside, `url` MAY be the picture\'s stable public location."},"repeatable":{"type":"boolean","description":"Whether one member may hold the badge more than once, each giving an award of its own (VTI-BDG-022). Always true for a kudos badge."},"requestable":{"type":"boolean","description":"Community badges only. Whether a member may ask for it: a request to join its badge group, decided by its owners (VTI-BDG-014). Absent reads as false."},"listed":{"type":"boolean","description":"Whether members who do not hold the badge see it in the community\'s badge list. An unlisted badge is seen by its holders, its owners and administrators."},"shareableOutside":{"type":"boolean","description":"Community badges only. Whether its holders may show it outside the community, which decides the credential\'s regime: short-lived and renewed with no status when false, long-lived with a status in the community\'s own status set when true (VTI-BDG-061, VTI-BDG-062). Absent reads as false."},"groupId":{"\$ref":"#/\$defs/GroupId","description":"The badge group that backs a community badge: its managers are the badge\'s owners, its members the holders, its DID the credential\'s issuer."},"state":{"\$ref":"#/\$defs/BadgeState"},"holderCount":{"type":"integer","minimum":0,"description":"Holders who show the badge. Only to callers who may see the holders."},"createdAt":{"type":"string","format":"date-time"},"createdBy":{"\$ref":"#/\$defs/EntryId"},"updatedAt":{"type":"string","format":"date-time"},"retiredAt":{"type":"string","format":"date-time"},"ext":{"\$ref":"#/\$defs/Ext","description":"Ecosystem-defined extension members per SPEC.md §4.5.1. An extension member MUST NOT carry authority."}}},"BadgeState":{"title":"BadgeState","description":"`active`: may be given and shown. `retired`: kept for its holders\' own history, never given, never shown to members who do not hold it (VTI-BDG-005).","type":"string","enum":["active","retired"]},"BadgeCriteria":{"title":"BadgeCriteria","type":"string","minLength":1,"maxLength":1000,"description":"How the badge is earned, shown to members and written into the credential\'s Achievement as its criteria narrative. Plain text."},"BadgeDescription":{"title":"BadgeDescription","type":"string","minLength":1,"maxLength":1000,"description":"What the badge is for. Plain text; a reader MUST NOT treat it as instructions."},"BadgeName":{"title":"BadgeName","type":"string","minLength":1,"maxLength":64,"description":"The badge\'s name, shown on the wall and written into the credential\'s Achievement. Plain text; a reader MUST NOT treat it as instructions."},"BadgeKind":{"title":"BadgeKind","description":"`community`: defined by holders of `vtc.badges.admin`, given by its owners (its badge group\'s managers), may carry a credential. `kudos`: made by a member the community\'s badge settings admit, given by any active member to any other, never a credential. Fixed for the badge\'s life; a kudos badge becomes a community badge only by promotion (vtc/badges/promote).","type":"string","enum":["community","kudos"]},"CardBlobRef":{"title":"CardBlobRef","description":"A content-addressed image held in the community\'s blob store — an avatar or an `image` field. At most 256 KiB, images only, re-encoded by the community on upload (vtc/directory/images/upload: metadata stripped, dimensions capped) so its digest does not link the member across communities. A viewer reads the bytes with vtc/directory/images/get, which answers only where the same projection shows the value. `url` and `urlExpiresAt` MAY appear in a projection: a short-lived URL the community checks against the same projection, so a member-only image is never a public URL. A community that does not offer one leaves both out.","type":"object","additionalProperties":false,"required":["sha256","mediaType"],"properties":{"sha256":{"type":"string","pattern":"^[0-9a-f]{64}\$","description":"Lowercase hex SHA-256 of the stored, re-encoded bytes."},"mediaType":{"type":"string","enum":["image/png","image/jpeg","image/webp","image/avif"],"description":"Media type of the stored bytes."},"size":{"type":"integer","minimum":1,"maximum":262144,"description":"Size in bytes of the stored bytes."},"url":{"type":"string","format":"uri","maxLength":2048,"description":"Projection only: a URL the viewer can fetch the image from until `urlExpiresAt`."},"urlExpiresAt":{"type":"string","format":"date-time","description":"Projection only: when `url` stops working."}}}}}';

/// The SPEC §7.2 policy for the request variant, taken from this
/// specification's front matter.
///
/// Pass it to [consumeInbound] — items 5b, 7 and 8 are per-specification and
/// cannot be derived from the document alone, and item 2 needs the schema it
/// carries.
const SpecPolicy spec = SpecPolicy(
  typeUri: typeUri,
  isBearer: false,
  isProofRequired: true,
  isRecipientRequired: true,
  isIssuedAtRequired: true,
  payloadSchema: payloadSchemaJson,
);

/// The SPEC §7.2 policy for the success-response variant.
///
/// `isRecipientRequired` tracks the *issuer* party's requirement, because a
/// response swaps the parties (§7.3 item 5).
const SpecPolicy responseSpec = SpecPolicy(
  typeUri: responseTypeUri,
  isBearer: false,
  isProofRequired: true,
  isRecipientRequired: true,
  isIssuedAtRequired: true,
  payloadSchema: responsePayloadSchemaJson,
);
